def isi_linimasa_transaksi_lama(apps, schema_editor):
    """Beri satu baris pembuka untuk transaksi yang sudah ada sebelum FR-32.

    Tanpa ini, membuka transaksi lama memperlihatkan linimasa kosong, dan itu
    terlihat seperti fitur yang rusak padahal cuma belum ada datanya. Waktunya
    diambil dari field `tanggal` transaksi itu sendiri, jadi urutannya tetap
    benar. Ditulis lewat update() karena `waktu` memakai auto_now_add dan
    tidak bisa diisi saat create.
    """
    TransaksiServis = apps.get_model("servis", "TransaksiServis")
    PembaruanServis = apps.get_model("servis", "PembaruanServis")

    for transaksi in TransaksiServis.objects.all().iterator():
        baris = PembaruanServis.objects.create(
            transaksi=transaksi,
            tahap="PERMINTAAN",
            keterangan="Transaksi servis dibuat.",
        )
        PembaruanServis.objects.filter(pk=baris.pk).update(waktu=transaksi.tanggal)


